
const ASSETS = {"Umbreon": "data:image/webp;base64,", "Azumarill": "data:image/webp;base64,", "Gengar": "data:image/webp;base64,", "Haunter": "data:image/webp;base64,", "Registeel": "data:image/webp;base64,", "Nidoqueen": "data:image/webp;base64,", "Magnezone": "data:image/webp;base64,", "Lanturn": "data:image/webp;base64,", "Machamp": "data:image/webp;base64,", "Sableye": "data:image/webp;base64,"};

const DEX = [
  { id: 'umbreon', name: 'Umbreon', type: 'Dark', typeClass: 'dark', img: ASSETS.Umbreon, favoriteFood: 'Biscoito Lunar', moodLine: 'curte descansar na sombra.' },
  { id: 'azumarill', name: 'Azumarill', type: 'Water', typeClass: 'water', img: ASSETS.Azumarill, favoriteFood: 'Berry Azul', moodLine: 'adora brincar perto da água.' },
  { id: 'gengar', name: 'Gengar', type: 'Ghost', typeClass: 'ghost', img: ASSETS.Gengar, favoriteFood: 'Doce Noturno', moodLine: 'parece estar planejando uma travessura.' },
  { id: 'nidoqueen', name: 'Nidoqueen', type: 'Poison', typeClass: 'poison', img: ASSETS.Nidoqueen, favoriteFood: 'Raiz Forte', moodLine: 'fica alerta protegendo o acampamento.' },
  { id: 'lanturn', name: 'Lanturn', type: 'Water', typeClass: 'water', img: ASSETS.Lanturn, favoriteFood: 'Bolinho de Luz', moodLine: 'ilumina tudo quando fica feliz.' },
  { id: 'sableye', name: 'Sableye', type: 'Dark', typeClass: 'dark', img: ASSETS.Sableye, favoriteFood: 'Pedrinha Doce', moodLine: 'olha para você esperando um carinho.' },
  { id: 'haunter', name: 'Haunter', type: 'Ghost', typeClass: 'ghost', img: ASSETS.Haunter, favoriteFood: 'Doce Sombrio', moodLine: 'ri baixinho quando recebe atenção.' },
  { id: 'registeel', name: 'Registeel', type: 'Steel', typeClass: 'steel', img: ASSETS.Registeel, favoriteFood: 'Mineral Brilhante', moodLine: 'permanece firme e silencioso.' },
  { id: 'magnezone', name: 'Magnezone', type: 'Electric', typeClass: 'electric', img: ASSETS.Magnezone, favoriteFood: 'Carga Crocante', moodLine: 'fica girando quando está animado.' },
  { id: 'machamp', name: 'Machamp', type: 'Fighting', typeClass: 'fighting', img: ASSETS.Machamp, favoriteFood: 'Shake Proteico', moodLine: 'quer treinar mais uma vez.' },
];

const STORAGE_KEY = 'scrypet_tamagotchi_v2';
const clamp = (value, min = 0, max = 100) => Math.max(min, Math.min(max, Math.round(value)));
const now = () => Date.now();
const root = document.querySelector('[data-root]');

function defaultPet(mon, index = 0) {
  return {
    dexId: mon.id,
    customName: mon.name,
    level: index === 0 ? 8 : 3,
    xp: index === 0 ? 42 : 0,
    hunger: 72 - index * 3,
    happiness: 68 + index * 2,
    energy: 78,
    bond: 12 + index * 4,
    health: 100,
    lastUpdate: now(),
    lastAction: 'Pronto para começar a jornada.',
    history: [{ at: now(), text: 'Entrou no acampamento.', icon: '🌿' }],
  };
}

function initialState() {
  return {
    selected: 'umbreon',
    session: 21,
    pets: Object.fromEntries(DEX.slice(0, 6).map((mon, index) => [mon.id, defaultPet(mon, index)])),
  };
}

let state = loadState();
let statusOpen = false;
let moreOpen = false;
let companionsOpen = false;
let selectedAction = null;

function loadState() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    if (!saved || !saved.pets) return initialState();
    const base = initialState();
    const merged = { ...base, ...saved, pets: { ...base.pets, ...saved.pets } };
    for (const [id, pet] of Object.entries(merged.pets)) {
      if (!Array.isArray(pet.history)) pet.history = [{ at: now(), text: 'Histórico iniciado.', icon: '🌿' }];
      if (!pet.customName) pet.customName = getDex(id).name;
      applyOfflineDecay(pet);
    }
    return merged;
  } catch {
    return initialState();
  }
}

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function getDex(id = state.selected) {
  return DEX.find(mon => mon.id === id) || DEX[0];
}

function getPet() {
  if (!state.pets[state.selected]) state.pets[state.selected] = defaultPet(getDex());
  return state.pets[state.selected];
}

function applyOfflineDecay(pet) {
  const elapsedHours = Math.max(0, (now() - (pet.lastUpdate || now())) / 3600000);
  if (elapsedHours < 0.02) return;
  pet.hunger = clamp(pet.hunger - elapsedHours * 4.2);
  pet.happiness = clamp(pet.happiness - elapsedHours * 1.6);
  pet.energy = clamp(pet.energy - elapsedHours * 2.1);
  if (pet.hunger < 18 || pet.energy < 10) {
    pet.health = clamp(pet.health - elapsedHours * 2.5);
  } else if (pet.health < 100) {
    pet.health = clamp(pet.health + elapsedHours * 1.2);
  }
  pet.lastUpdate = now();
}

function moodFor(pet) {
  const avg = (pet.hunger + pet.happiness + pet.energy + pet.health) / 4;
  if (pet.hunger < 25) return { label: 'Com fome', icon: '🍎', className: 'danger', note: 'está com fome!' };
  if (pet.energy < 20) return { label: 'Sonolento', icon: '💤', className: 'sleepy', note: 'quer descansar.' };
  if (avg >= 82) return { label: 'Animado', icon: '✨', className: 'happy', note: 'está animado!' };
  if (avg >= 58) return { label: 'Tranquilo', icon: '🌿', className: 'calm', note: 'está tranquilo.' };
  return { label: 'Carente', icon: '💛', className: 'warning', note: 'quer atenção.' };
}

function xpNeeded(pet) {
  return 80 + pet.level * 18;
}

function addHistory(pet, icon, text) {
  pet.history = [{ at: now(), icon, text }, ...(pet.history || [])].slice(0, 12);
}

function addXp(pet, amount) {
  pet.xp += amount;
  let leveled = false;
  while (pet.xp >= xpNeeded(pet)) {
    pet.xp -= xpNeeded(pet);
    pet.level += 1;
    pet.bond = clamp(pet.bond + 5);
    leveled = true;
  }
  if (leveled) {
    addHistory(pet, '⭐', `${pet.customName} subiu para o nível ${pet.level}.`);
    showToast(`${pet.customName} subiu para o nível ${pet.level}!`);
  }
}

const ACTIONS = {
  feed: {
    label: 'Alimentar', icon: '🍎', short: 'Comida',
    run(pet, mon) {
      pet.hunger = clamp(pet.hunger + 23);
      pet.happiness = clamp(pet.happiness + 4);
      pet.energy = clamp(pet.energy + 3);
      addXp(pet, 12);
      pet.lastAction = `${pet.customName} comeu ${mon.favoriteFood}.`;
      addHistory(pet, '🍎', pet.lastAction);
    }
  },
  play: {
    label: 'Brincar', icon: '✨', short: 'Brincar',
    run(pet) {
      if (pet.energy < 12) return false;
      pet.happiness = clamp(pet.happiness + 20);
      pet.energy = clamp(pet.energy - 10);
      pet.hunger = clamp(pet.hunger - 5);
      pet.bond = clamp(pet.bond + 3);
      addXp(pet, 16);
      pet.lastAction = `${pet.customName} brincou no acampamento.`;
      addHistory(pet, '✨', pet.lastAction);
    }
  },
  sleep: {
    label: 'Dormir', icon: '💤', short: 'Dormir',
    run(pet) {
      pet.energy = clamp(pet.energy + 32);
      pet.happiness = clamp(pet.happiness + 3);
      pet.hunger = clamp(pet.hunger - 4);
      addXp(pet, 8);
      pet.lastAction = `${pet.customName} descansou um pouco.`;
      addHistory(pet, '💤', pet.lastAction);
    }
  },
  train: {
    label: 'Treinar', icon: '🏅', short: 'Treino',
    run(pet) {
      if (pet.energy < 22 || pet.hunger < 18) return false;
      pet.energy = clamp(pet.energy - 18);
      pet.hunger = clamp(pet.hunger - 9);
      pet.happiness = clamp(pet.happiness + 10);
      pet.bond = clamp(pet.bond + 4);
      addXp(pet, 28);
      pet.lastAction = `${pet.customName} treinou com você.`;
      addHistory(pet, '🏅', pet.lastAction);
    }
  },
};

function doAction(key) {
  const pet = getPet();
  const mon = getDex();
  selectedAction = key;
  applyOfflineDecay(pet);
  const ok = ACTIONS[key].run(pet, mon);
  pet.health = clamp(pet.health + (pet.hunger > 45 && pet.energy > 25 ? 2 : 0));
  pet.lastUpdate = now();
  saveState();
  render();
  if (ok === false) showToast(`${pet.customName} precisa de comida ou energia antes disso.`);
  else showToast(pet.lastAction);
  setTimeout(() => { selectedAction = null; render(); }, 540);
}

function selectPet(id) {
  if (!state.pets[id]) state.pets[id] = defaultPet(getDex(id));
  state.selected = id;
  companionsOpen = false;
  moreOpen = false;
  saveState();
  render();
  showToast(`${getDex(id).name} agora está no acampamento.`);
}

function resetDemo() {
  if (!confirm('Resetar o protótipo e voltar aos status iniciais?')) return;
  state = initialState();
  statusOpen = false;
  moreOpen = false;
  companionsOpen = false;
  saveState();
  render();
  showToast('Protótipo reiniciado.');
}

function goBack() {
  showToast('Voltando para o perfil...');
  setTimeout(() => {
    if (history.length > 1) history.back();
  }, 380);
}

function showToast(message) {
  const toast = document.querySelector('[data-toast]');
  toast.textContent = message;
  toast.classList.add('show');
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => toast.classList.remove('show'), 2600);
}

function formatTime(ts) {
  const date = new Date(ts);
  return date.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
}

function statBar(name, value, icon) {
  const safe = clamp(value);
  return `
    <div class="stat-row">
      <div class="stat-label"><span>${icon}</span>${name}</div>
      <div class="stat-track"><i style="width:${safe}%"></i></div>
      <strong>${safe}</strong>
    </div>`;
}

function miniCompanion(mon) {
  const pet = state.pets[mon.id] || defaultPet(mon);
  const mood = moodFor(pet);
  const low = pet.hunger < 30 || pet.energy < 18 || pet.health < 45;
  return `
    <button class="companion-row ${state.selected === mon.id ? 'active' : ''}" type="button" data-select="${mon.id}" aria-label="Selecionar ${mon.name}">
      <span class="mini-orb ${low ? 'needs-care' : ''}"><img src="${mon.img}" alt="${mon.name}" loading="lazy"></span>
      <span class="companion-copy"><b>${mon.name}</b><small>${mood.icon} ${mood.label} · Nv. ${pet.level}</small></span>
      <span class="companion-chevron">›</span>
    </button>`;
}

function recentHistory(pet) {
  const items = (pet.history || []).slice(0, 5);
  if (!items.length) return '<p class="empty-history">Nenhum cuidado registrado ainda.</p>';
  return `<div class="history-list">${items.map(item => `
    <div class="history-item">
      <span>${item.icon || '•'}</span>
      <p>${item.text}<small>${formatTime(item.at)}</small></p>
    </div>`).join('')}</div>`;
}

function render() {
  const pet = getPet();
  const mon = getDex();
  applyOfflineDecay(pet);
  saveState();

  const mood = moodFor(pet);
  const xpPercent = Math.min(100, (pet.xp / xpNeeded(pet)) * 100);
  const needsCare = pet.hunger < 30 || pet.energy < 18 || pet.health < 45;
  const hungry = pet.hunger < 30;
  const anyNeedsCare = Object.values(state.pets).some(p => p.hunger < 30 || p.energy < 18 || p.health < 45);
  const selectedImgStyle = selectedAction ? ` action-${selectedAction}` : '';

  root.innerHTML = `
    <section class="phone-shell">
      <header class="topbar" aria-label="Resumo do companheiro">
        <button class="pokeball-button ${needsCare ? 'alert' : ''}" type="button" data-status-toggle aria-label="Abrir status do companheiro">
          <span class="pokeball-icon"><i></i></span>
          ${needsCare ? '<em></em>' : ''}
        </button>
        <div class="name-block">
          <div class="name-line">
            <strong>${pet.customName}</strong>
            <span class="type-pill ${mon.typeClass}">${mon.type}</span>
          </div>
          <div class="xp-bar" aria-label="Experiência"><i style="width:${xpPercent}%"></i></div>
        </div>
        <div class="level-card">
          <span>Nv.</span>
          <strong>${pet.level}</strong>
        </div>
      </header>

      <aside class="status-dropdown ${statusOpen ? 'open' : ''}" aria-live="polite">
        <div class="status-card">
          <div class="drop-arrow"></div>
          <div class="status-head">
            <span class="status-avatar"><img src="${mon.img}" alt="${mon.name}"></span>
            <div><small>Status do companheiro</small><h2>${pet.customName}</h2></div>
            <button class="close-panel" type="button" data-status-toggle aria-label="Fechar status">×</button>
          </div>
          ${needsCare ? `<div class="status-alert"><b>${hungry ? '🍎 Está com fome!' : '⚠ Precisa de atenção!'}</b><span>Use os botões de cuidado para melhorar o humor.</span></div>` : `<div class="status-alert good"><b>✨ Tudo certo!</b><span>${pet.customName} está bem cuidado.</span></div>`}
          <div class="status-grid">
            ${statBar('Fome', pet.hunger, '🍎')}
            ${statBar('Felicidade', pet.happiness, '✨')}
            ${statBar('Energia', pet.energy, '💤')}
            ${statBar('Saúde', pet.health, '❤')}
            ${statBar('Vínculo', pet.bond, '🤝')}
          </div>
          <div class="last-action"><b>Última ação</b><p>${pet.lastAction}</p></div>
        </div>
      </aside>

      <main class="camp-area ${mood.className}">
        <div class="sky-sparkle s1"></div><div class="sky-sparkle s2"></div><div class="sky-sparkle s3"></div>
        <div class="mood-pill ${needsCare ? 'need' : ''}"><span>${mood.icon}</span><b>${mood.label}</b></div>
        ${hungry ? `<div class="need-bubble"><span>🍎</span> ${pet.customName} está com fome!</div>` : ''}
        <div class="tent" aria-hidden="true"><i></i></div>
        <button class="pet-stage ${selectedImgStyle}" type="button" data-status-toggle aria-label="Abrir status de ${pet.customName}">
          <span class="pet-aura"></span>
          <img src="${mon.img}" alt="${mon.name}" draggable="false">
          <span class="pet-shadow"></span>
        </button>
        <div class="speech"><b>${mood.icon} ${mood.note}</b><br>${pet.customName} ${mon.moodLine}</div>
        <div class="flowers f1"></div><div class="flowers f2"></div><div class="grass g1"></div><div class="grass g2"></div>
      </main>

      <button class="companions-fab ${anyNeedsCare ? 'alert' : ''}" type="button" data-companions-toggle aria-label="Abrir companheiros">
        <span class="stacked-faces">
          ${DEX.slice(0,3).map(m => `<img src="${m.img}" alt="" aria-hidden="true">`).join('')}
        </span>
        <i>+</i>
      </button>

      <section class="care-sheet ${moreOpen ? 'expanded' : ''}" aria-label="Cuidar do Tamagotchi">
        <button class="more-toggle" type="button" data-more-toggle aria-expanded="${moreOpen}">
          <span>${moreOpen ? '⌄' : '⌃'}</span>
          <b>${moreOpen ? 'Fechar' : 'Mais'}</b>
        </button>

        <div class="more-panel" ${moreOpen ? '' : 'inert'}>
          <div class="more-card history-card">
            <div class="more-title"><span>📜</span><b>Histórico</b></div>
            ${recentHistory(pet)}
          </div>
          <div class="more-actions">
            <button type="button" class="soft-option" data-companions-toggle><span>👥</span>Companheiros</button>
            <button type="button" class="soft-option" data-go-back><span>↩</span>Voltar</button>
            <button type="button" class="soft-option danger" data-reset><span>↺</span>Reset</button>
          </div>
        </div>

        <div class="action-dock">
          ${Object.entries(ACTIONS).map(([key, action]) => `
            <button class="action-btn action-${key}-btn ${selectedAction === key ? 'active' : ''}" data-action="${key}" type="button" aria-label="${action.label}">
              <span>${action.icon}</span><b>${action.short}</b>
            </button>`).join('')}
        </div>
      </section>

      <aside class="companions-drawer ${companionsOpen ? 'open' : ''}" aria-label="Lista de companheiros">
        <div class="drawer-card">
          <div class="drawer-head">
            <div><small>Equipe do perfil</small><h2>Companheiros</h2></div>
            <button type="button" class="close-panel" data-companions-toggle>×</button>
          </div>
          <div class="companions-list">${DEX.map(miniCompanion).join('')}</div>
        </div>
      </aside>
    </section>
  `;

  document.querySelectorAll('[data-action]').forEach(btn => btn.addEventListener('click', () => doAction(btn.dataset.action)));
  document.querySelectorAll('[data-select]').forEach(btn => btn.addEventListener('click', () => selectPet(btn.dataset.select)));
  document.querySelectorAll('[data-status-toggle]').forEach(btn => btn.addEventListener('click', () => { statusOpen = !statusOpen; companionsOpen = false; render(); }));
  document.querySelectorAll('[data-more-toggle]').forEach(btn => btn.addEventListener('click', () => { moreOpen = !moreOpen; statusOpen = false; render(); }));
  document.querySelectorAll('[data-companions-toggle]').forEach(btn => btn.addEventListener('click', () => { companionsOpen = !companionsOpen; statusOpen = false; render(); }));
  document.querySelectorAll('[data-reset]').forEach(btn => btn.addEventListener('click', resetDemo));
  document.querySelectorAll('[data-go-back]').forEach(btn => btn.addEventListener('click', goBack));
}

render();
setInterval(() => {
  for (const pet of Object.values(state.pets)) applyOfflineDecay(pet);
  saveState();
  render();
}, 60000);
